const genericCode={
 root:`def biseccion(f, a, b, tol=1e-6, max_iter=100):\n    if f(a) == 0: return a\n    if f(b) == 0: return b\n    if f(a)*f(b) > 0: raise ValueError("Falta cambio de signo")\n    for _ in range(max_iter):\n        c = (a+b)/2\n        if f(c) == 0 or (b-a)/2 <= tol: return c\n        if f(a)*f(c) < 0: b = c\n        else: a = c\n    raise RuntimeError("No se alcanzó la tolerancia")`,
 linear:`def residuo(A, x, b):\n    return max(abs(sum(a*v for a,v in zip(fila,x))-bi)\n               for fila,bi in zip(A,b))\n\n# Verifica siempre la solución en el sistema original.\nA = [[4., 1.], [1., 3.]]\nx = [1., 2.]\nb = [6., 7.]\nprint(residuo(A, x, b))  # 0`,
 fit:`def newton_datos(x, y, t):\n    if len(set(x)) != len(x): raise ValueError("Nodos repetidos")\n    c = list(y)\n    for j in range(1, len(x)):\n        for i in range(len(x)-1, j-1, -1):\n            c[i] = (c[i]-c[i-1])/(x[i]-x[i-j])\n    p = c[-1]\n    for i in range(len(x)-2, -1, -1):\n        p = c[i] + (t-x[i])*p\n    return p`,
 integration:`def simpson(f, a, b, n):\n    if n < 2 or n % 2: raise ValueError("n debe ser par y positivo")\n    h = (b-a)/n\n    s = f(a)+f(b)\n    s += sum((4 if i%2 else 2)*f(a+i*h) for i in range(1,n))\n    return h*s/3\n\nprint(simpson(lambda x: x*x, 0., 1., 8))  # 1/3`
};
